// Evidence validation per SPEC §9.2 / §4.2. Pure.
import type { EvidenceRefV1 } from "./types";

const VALID_KINDS: EvidenceRefV1["kind"][] = ["omp_event", "tool_result", "verification", "child_result"];

export function isValidEvidenceRef(ref: EvidenceRefV1): boolean {
  if (!ref || typeof ref !== "object") return false;
  if (typeof ref.id !== "string" || ref.id.length === 0) return false;
  if (!VALID_KINDS.includes(ref.kind)) return false;
  if (ref.integrity !== "confirmed" && ref.integrity !== "partial") return false;
  // Anchor requirements: a real, readable event/result, not a model assertion.
  if (typeof ref.sourceId !== "string" || ref.sourceId.length === 0) return false;
  if (typeof ref.observedAt !== "string" || ref.observedAt.length === 0) return false;
  if (typeof ref.summary !== "string" || ref.summary.length === 0) return false;
  return true;
}

/** A confirmed anchor is required to pass the convergence gate (SPEC §9.2). */
export function isConfirmedAnchor(ref: EvidenceRefV1): boolean {
  return isValidEvidenceRef(ref) && ref.integrity === "confirmed";
}

export function hasConfirmedEvidence(refs: EvidenceRefV1[]): boolean {
  return refs.some(isConfirmedAnchor);
}

/** Reject decisions that rely solely on unanchored model self-report. */
export function isModelSelfReportOnly(refs: EvidenceRefV1[]): boolean {
  if (refs.length === 0) return true;
  return refs.every((r) => !isValidEvidenceRef(r));
}

/** Normalize a failure signature for duplicate-action detection (SPEC §13). */
export function normalizeFailureSignature(refs: EvidenceRefV1[]): string {
  return refs
    .map((r) => r.failureSignature ?? `${r.kind}:${r.sourceId}`)
    .sort()
    .join("|");
}

// WEConverge core types — faithful to SPEC §4 / §5.1.
// Pure types only; no runtime OMP dependency.
//
// Implementation extensions beyond SPEC §4 literal shapes (authorized by the
// 2026-08-20 Owner supplementary contract; none weaken any SPEC invariant):
//  - SessionStateV1.lastEffortRaiseAt: proves "new verified attempt since last raise"
//    from anchored evidence timestamps instead of a model-claimed boolean (SPEC §11.2.5).
//  - AuditEventV1.eventId: SPEC §9.0 requires returning auditEventId, so events carry ids.
//  - AuditEventV1.costComparison: SPEC §13 requires candidates/exclusions/tiers/choice in audit.

export type SemanticAction =
  | "continue_current"
  | "activate_alternative"
  | "delegate_bounded_work"
  | "invoke_specialist"
  | "explore_in_parallel"
  | "raise_effort"
  | "report_source_gap"
  | "report_blocked";

export type DifficultyType =
  | "path_unclear"
  | "reasoning_depth_insufficient"
  | "domain_mismatch"
  | "bounded_mechanical_work"
  | "alternative_ready"
  | "source_missing"
  | "proven_blocker";

/** `max` is only for detection/rejection, never an automatic state-machine target. */
export type Effort = "medium" | "high" | "xhigh" | "max" | "unknown";

export type Phase =
  | "disabled"
  | "baseline"
  | "executing"
  | "external_exploration"
  | "integrating"
  | "source_gap"
  | "blocked"
  | "completed"
  | "degraded";

export type Integrity =
  | "confirmed"
  | "partial"
  | "source_gap"
  | "blocked"
  | "failed"
  | "stale"
  | "degraded";

export interface EvidenceRefV1 { … }

export interface ConvergenceDecisionV1 { … }

export interface ResolvedRouteV1 { … }

export interface SessionStateV1 { … }

export interface ConfigV1 { … }

/** SPEC §13: candidates, exclusion reasons, cost tiers and the final choice must be auditable. */
export interface CostComparisonV1 { … }

export interface AuditEventV1 { … }

// ---- Injected OMP adapters (implemented only in wiring layer) ----
export interface ChildSpec { … }

/** Actual route of a specific child agent, read back per child (never inferred from parent). */
export interface ChildRoute { … }

export interface OmpAdapters { … }

export const DEFAULT_CONFIG: ConfigV1 = { … };

// Allowed automatic effort targets (REQ-030/REQ-032). `max` excluded.
export const AUTO_EFFORTS: Effort[] = ["medium", "high", "xhigh"];
export const BLOCKED_RESULT: Integrity = "blocked";

