  // observe tool_call/tool_result for cross-check
  try{
    pi.on("tool_call", (ev)=>{ sa({kind:"event_tool_call", tool:ev?.toolName??ev?.name??"unknown", paramsPreview: trunc(JSON.stringify(ev?.params??{}).slice(0,300),300)}); return undefined; });
  }catch{}
  try{
    pi.on("tool_result", (ev)=>{ sa({kind:"event_tool_result", tool:ev?.toolName??ev?.name??"unknown"}); return undefined; });
  }catch{}
  try{
    pi.events?.on?.("task:subagent:lifecycle", (ev)=>{ sa({kind:"event_lifecycle", payload:{childId:ev?.childId??ev?.id??null, agent:ev?.agent??null, status:ev?.status??null}}); });
  }catch{}
}

